REPORT_CSS = """
:root{color-scheme:dark;--canvas:#05070a;--well:#030407;--panel:#0b1116;--raised:#111822;--border:#1e2e2a;--text:#d6e5e3;--muted:#a0b7b1;--teal:#0df2c9;--violet:#d7a4ff;--red:#ff879a}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:24px}body{margin:0;background:var(--canvas);color:var(--text);font:14px/1.7 'JetBrains Mono',monospace}body::before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-1;background:linear-gradient(transparent 50%,#0002 50%);background-size:100% 4px}::selection{background:var(--teal);color:var(--well)}a{color:var(--teal);text-underline-offset:4px}a:hover{color:#c7ffec}a:focus-visible,summary:focus-visible{outline:2px solid var(--teal);outline-offset:5px}h1,h2,h3,.wordmark{font-family:Cinzel,Georgia,serif;font-weight:700;line-height:1.35}h1{font-size:clamp(32px,4.6vw,56px);margin:18px 0;letter-spacing:-.025em}h2{font-size:22px;margin:0}h3{font-size:16px;margin:0 0 12px}p{margin:12px 0}small{font-size:11px;color:var(--muted);overflow-wrap:anywhere}strong{font-weight:700}.shell{width:min(1280px,100%);margin:auto;padding:0 32px}.masthead{border-bottom:1px solid var(--border);background:var(--well)}.masthead-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:94px}.identity{display:flex;gap:14px;align-items:center;text-decoration:none}.seal{width:46px;height:46px;flex-shrink:0;display:grid;place-items:center;border:1px solid #0df2c955;box-shadow:0 0 18px #0df2c91a;background:#06110f}.seal svg{width:34px;height:34px;color:var(--teal)}.wordmark{font-size:20px;letter-spacing:.08em;color:var(--teal)}.eyebrow,.tag,.status,.nav,.section-index,.stat-label,summary,.button,.stamp{font-family:'Space Mono',monospace;font-size:11px;letter-spacing:.05em}.eyebrow{color:var(--muted);text-transform:uppercase;margin-top:3px}.stamp{text-align:right;color:var(--muted);max-width:330px;overflow-wrap:anywhere}.stamp b{color:var(--violet);font-weight:400}.nav{display:flex;flex-wrap:wrap;gap:8px;padding:14px 0}.nav a{padding:7px 12px;text-decoration:none;color:var(--muted);border:1px solid transparent}.nav a:hover{border-color:#0df2c955;color:var(--teal);background:#08332b55}.nav a:last-child{margin-left:auto;color:var(--teal)}main{padding-top:26px!important;padding-bottom:40px!important}.hero{display:grid;grid-template-columns:1.15fr 1fr;align-items:center;gap:36px;padding:38px;background:radial-gradient(ellipse at 0 100%,#a855f714,transparent 60%),linear-gradient(110deg,#0b1116,#06110f);border:1px solid #0df2c955;position:relative;clip-path:polygon(0 0,calc(100% - 14px) 0,100% 14px,100% 100%,0 100%)}.hero::after{content:'';position:absolute;inset:0;pointer-events:none;opacity:.16;background:repeating-linear-gradient(0deg,transparent 0,transparent 3px,#0df2c911 4px)}.hero-copy,.stats{position:relative;z-index:1}.tag,.status{display:inline-block;padding:4px 9px;border:1px solid #0df2c966;color:var(--teal);background:#08332b66;font-size:10px}.tag{font-size:10px}.tag.secondary{color:var(--violet);border-color:#a855f766;background:#a855f714}.hook{font-size:15px;color:#c7ffec;max-width:500px}.intro{color:var(--muted);font-size:12px;max-width:570px}.stats{display:grid;grid-template-columns:1fr 1fr;background:var(--well);border:1px solid var(--border)}.stat{padding:24px 20px;min-width:0}.stat:nth-child(odd){border-right:1px solid var(--border)}.stat:nth-child(-n+2){border-bottom:1px solid var(--border)}.stat-value{display:block;font-size:30px;font-weight:600;color:var(--teal);line-height:1.3;overflow-wrap:anywhere}.stat:nth-child(2) .stat-value,.stat:nth-child(3) .stat-value{color:var(--violet)}.stat-label{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;margin-top:8px}.stat-value.words{font-size:20px}.section-heading{display:flex;gap:14px;align-items:center;margin:38px 0 18px}.section-index{color:var(--teal);border:1px solid #0df2c944;padding:3px 7px;flex-shrink:0}.section-heading::after{content:'';height:1px;background:var(--border);flex:1;min-width:10px}.scenario-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.panel,article{min-width:0;background:var(--panel);border:1px solid var(--border);padding:22px}.scenario{border-top:2px solid #a855f77a}.scenario h3{overflow-wrap:anywhere;margin:16px 0 12px}.scenario p{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.scenario .disposition{color:var(--violet);font-size:11px}.scenario .scenario-number{font:11px 'Space Mono',monospace;color:var(--violet);letter-spacing:.1em}.scenario::after{content:'';display:block;margin-top:18px;height:1px;background:linear-gradient(90deg,#a855f777,transparent)}.boundary-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(0,1fr);gap:22px;align-items:start}.table-panel{padding:10px 18px}table{width:100%;border-collapse:collapse;font-size:12px}td{padding:12px 8px;border-bottom:1px solid var(--border);overflow-wrap:anywhere}tr:last-child td{border-bottom:0}td:last-child{text-align:right;min-width:74px;color:var(--muted)}.state-pass td:last-child{color:var(--teal)}.state-fail td:last-child{color:var(--red)}.side-stack{display:grid;gap:18px}.panel h3{color:#c7ffec}.role-list{list-style:none;margin:18px 0 0;padding:0}.role-list li{padding:10px 0;border-top:1px solid var(--border);font-size:12px;color:var(--muted)}.role-list b{color:var(--violet);display:inline-block;min-width:108px}.note{font-size:12px;color:var(--muted)}.button{display:inline-block;text-align:center;padding:12px 18px;background:var(--teal);color:#002b22;text-decoration:none;border:1px solid var(--teal);font-weight:700;clip-path:polygon(0 0,calc(100% - 7px) 0,100% 7px,100% 100%,0 100%)}.button:hover{background:#c7ffec;color:#002b22}.rehearsal-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.rehearsal-card{border-top:2px solid #0df2c966}.rehearsal-card h3{overflow-wrap:anywhere;font-size:15px}.rehearsal-card .status{margin:3px 0 12px}.status.failed{color:var(--red);border-color:#ff879a66;background:#2e0b16}.status.control{color:var(--violet);border-color:#a855f766;background:#a855f714}details{margin-top:12px}summary{cursor:pointer;color:var(--muted);line-height:1.6;padding:7px 0;font-size:10px}details[open] summary{color:var(--teal)}details table{font-size:10px;table-layout:fixed}details td{padding:10px 3px}details td:first-child{width:56%}details td:last-child{min-width:0}.hash{display:block;margin:18px 0}.model-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.model-card{border-left:2px solid #a855f788}.model-card h3{color:var(--violet)}.model-card p{font-size:12px}.model-card .metrics{font-size:11px;color:var(--teal);margin-top:20px;padding-top:14px;border-top:1px solid var(--border)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--well);padding:20px;border:1px solid var(--border);font-size:12px}.footer{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;border-top:1px solid var(--border);padding:26px 0;margin-top:36px}.footer p{margin:0;color:var(--teal);font-size:12px}.footer small{display:block;margin-top:7px}.skip{position:absolute;left:20px;top:-80px;z-index:10;padding:12px;background:var(--teal);color:var(--well)}.skip:focus{top:8px}
.button:focus-visible{clip-path:none}
@media(min-width:1450px){.shell{width:min(1440px,100%)}}@media(max-width:1000px){.hero{grid-template-columns:1fr;gap:24px;padding:28px}.scenario-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.boundary-layout{grid-template-columns:1fr}.side-stack{grid-template-columns:1fr 1fr}.rehearsal-grid{grid-template-columns:1fr}.rehearsal-card details table{table-layout:auto}.rehearsal-card details td:first-child{width:auto}}
@media(max-width:600px){body{font-size:13px}.shell{padding:0 16px}.masthead-inner{align-items:flex-start;flex-direction:column;gap:12px;padding-top:20px;padding-bottom:18px}.wordmark{font-size:17px}.stamp{text-align:left;font-size:10px}.eyebrow{font-size:9px}.nav{gap:2px}.nav a{padding:8px;font-size:10px}.nav a:last-child{margin-left:0}.hero{padding:22px 18px}.tag{font-size:9px}.stat{padding:18px 12px}.stat-value{font-size:26px}.stat-label{font-size:9px}.stat-value.words{font-size:17px}.scenario-grid,.side-stack,.model-grid{grid-template-columns:1fr}h2{font-size:18px}.section-heading{gap:10px}.panel,article{padding:18px}.table-panel{padding:8px}td{padding:11px 5px;font-size:11px}.section-heading::after{display:none}.footer{gap:12px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}@media print{body{background:white;color:black}body::before{display:none}.masthead,.hero,.panel,article,.stats{background:white;color:black;clip-path:none}.nav{display:none}a,.wordmark,h1,h2,h3,.stat-value,.hook,.footer p{color:black!important}.shell{width:100%;padding:0}.hero{grid-template-columns:1fr}.scenario-grid,.model-grid,.boundary-layout{grid-template-columns:1fr}.rehearsal-grid{grid-template-columns:1fr}details{display:block}article,.panel{break-inside:avoid}}
"""
